<script lang="ts">
 import {permitted,canRequest,currentAccount} from './accounts';
 import RequestDownload from './RequestDownload.svelte';import PosterEditor from './PosterEditor.svelte';
 import {onMount} from 'svelte';import Portrait from './Portrait.svelte';import AlbumMatch from './AlbumMatch.svelte';import Icon from './Icon.svelte';import MediaShelf from './MediaShelf.svelte';import {groupMedia} from './collection';import {groupCard,workCard,trackEntry,timeLabel,type Card} from './experience';import type {Entry,Work,Provider,Contributor} from './types';
 export let card:Card;export let entries:Entry[];export let works:Work[];export let providers:Provider[];export let token:string;export let play:(e:Entry,restart?:boolean)=>void;export let enqueue:(e:Entry[])=>void;export let playlist:(e:Entry[])=>void;export let inspect:(e:Entry)=>void;export let open:(c:Card)=>void;export let person:(provider:string,person:Contributor)=>void;export let artist:(name:string)=>void;export let changed:(w:Work)=>void;export let refresh:()=>Promise<void>;export let mark:(e:Entry,v:boolean)=>void;
 let editingPoster=false;let posterEpoch=0;let downloadSeason:number|null=null;let matching=false;let selectedSeason:number|null=null;let failedImage='';let failedSeasons:Record<number,boolean>={};let failedTrailers:Record<string,boolean>={};let work:Work|undefined=card.work;let busy=false;let warning='';let related:Work[]=[];let alive=true;let requested='';const abort=new AbortController();
 $: local=work?entries.filter(e=>work?.localIds.includes(e.id)):card.group?entries.filter(e=>card.group?.entries.some(a=>a.id===e.id)):card.entry?[entries.find(e=>e.id===card.entry?.id)||card.entry]:[];
 $: sorted=[...local].sort((a,b)=>(a.metadata?.season??a.metadata?.disc??0)-(b.metadata?.season??b.metadata?.disc??0)||(a.metadata?.episode??a.metadata?.track??0)-(b.metadata?.episode??b.metadata?.track??0));
 $: trackMode=!!card.entry&&card.entry.kind==='music';
 $: m=work?.metadata||card.group?.entries[0]?.metadata||card.entry?.metadata;
 $: title=trackMode?(card.entry?.metadata?.title||card.title):(work?.metadata.title||card.title);
 $: automaticPicture=work?.poster?`/api/v1/discovery/works/${work.id}/poster?automatic=1`:local.find(e=>e.metadata?.imageId)?.metadata?.imageId?`/api/v1/artwork/${local.find(e=>e.metadata?.imageId)!.metadata!.imageId}`:card.image?.startsWith('/api/v1/posters/')?undefined:card.image;
 $: picture=local.find(e=>e.posterUrl)?.posterUrl||work?.posterUrl||automaticPicture;
 $: fallbackImage=card.group?.imageId?`/api/v1/artwork/${card.group.imageId}`:card.entry?.metadata?.imageId?`/api/v1/artwork/${card.entry.metadata.imageId}`:undefined;
 $: displayedImage=failedImage===picture?fallbackImage:picture;
 $: seasonCards=(m?.seasons?.length?m.seasons:[...new Set(sorted.map(e=>e.metadata?.season??0))].map(number=>({number,name:number===0?'Épisodes spéciaux':`Saison ${number}`,episodes:0,image:undefined}))).filter(s=>card.kind==='series'&&(s.episodes>0||sorted.some(e=>(e.metadata?.season??0)===s.number)));
 $: seasonEntries=selectedSeason===null?sorted:sorted.filter(e=>(e.metadata?.season??0)===selectedSeason);
 $: first=trackMode?(sorted.find(e=>e.id===card.entry?.id)||card.entry):(sorted.find(e=>!e.completed)||sorted[0]);
 $: people=trackMode?m?.tracks?.find(t=>trackEntry(t,local)?.id===card.entry?.id)?.artists||m?.contributors||[]:m?.contributors||[];
 $: album=groupMedia(entries).find(g=>g.entries.some(e=>e.id===card.entry?.id));
 $: unmatched=work?.metadata.tracks?.length?sorted.filter(e=>!work?.metadata.tracks?.some(t=>trackEntry(t,sorted)?.id===e.id)):[];
 onMount(()=>{void load();return()=>{alive=false;abort.abort();};});
 async function request(path:string,method='GET',body?:unknown){const r=await fetch('/api/v1/'+path,{method,headers:{'Content-Type':'application/json','X-Mosaune-Token':token},body:body===undefined?undefined:JSON.stringify(body),signal:abort.signal});if(r.status===204)return null;const data=await r.json();if(!r.ok)throw new Error(data.error||'Opération indisponible.');return data;}
 async function load(){busy=true;try{
 if(!work){const entry=card.group?.entries[0]||card.entry;work=works.find(w=>w.localIds.includes(entry?.id??''));}
 if(work){const data=await request('discovery/works/'+work.id);if(!alive)return;work=data.work;warning=data.warning;changed(data.work);if(work&&providers.some(p=>p.id===work?.metadata.provider&&p.configured&&p.discovery)){try{const more=await request('discovery/browse','POST',{provider:work.metadata.provider,kind:work.kind,seed:work.id,page:1});if(alive)related=more.items;}catch{if(alive)warning+=(warning?' ':'')+'Les suggestions sont momentanément indisponibles.';}}}
 }catch(e){if(alive)warning=e instanceof Error?e.message:'Fiche indisponible.';}finally{if(alive)busy=false;}}
 async function toggle(field:'favorite'|'watchlist'){if(!work)return;busy=true;try{const updated=await request('discovery/works/'+work.id,'PATCH',{[field]:!work[field]});if(alive){work=updated;changed(updated);}}catch(e){if(alive)warning=e instanceof Error?e.message:'Liste non enregistrée.';}finally{if(alive)busy=false;}}
 async function posterSaved(){await refresh();if(work){const data=await request('discovery/works/'+work.id);work=data.work;changed(data.work);}failedImage='';posterEpoch++;}
 async function matched(candidate:Work){await refresh();const data=await request('discovery/works/'+candidate.id);work=data.work;changed(data.work);await load();}

 function openTrack(entry:Entry){open({key:entry.id,title:entry.metadata?.title||entry.name,subtitle:entry.metadata?.artist||'',kind:'music',local:true,entry,image:picture});}
 function requestLater(title:string){requested=`« ${title} » : les demandes de téléchargement ne sont pas encore raccordées. Aucune demande n’a été envoyée.`;}
</script>
{#if editingPoster}<PosterEditor scope={local[0]?.libraryId?'media':'works'} id={local[0]?.libraryId?local[0].id:work!.id} {title} current={displayedImage} {token} saved={posterSaved} close={()=>editingPoster=false}/>{/if}
<article class="content-page">
 <section class="content-hero" class:album-hero={card.kind==='music'}>
 <div class="content-cover">{#if displayedImage}<img src={displayedImage+(displayedImage.includes('?')?'&':'?')+'display='+posterEpoch} alt={`Affiche de ${title}`} onerror={()=>{if(displayedImage===fallbackImage)fallbackImage=undefined;failedImage=picture||'';}}/>{:else}<Icon name={card.kind} size={64}/>{/if}</div>
 <div class="content-copy"><span class="eyebrow">{trackMode?'MORCEAU':card.kind==='music'?'ALBUM':card.kind==='series'?'SÉRIE':'FILM'} · {local.length?'DANS VOTRE COLLECTION':'À DÉCOUVRIR'}</span><h1>{title}</h1>
 <div class="content-facts">{#if m?.year}<span>{m.year}</span>{/if}{#if m?.runtime}<span>{m.runtime} min</span>{/if}{#if m?.genres?.length}<span>{m.genres.join(' · ')}</span>{/if}{#if m?.voteCount}<span>★ {m.rating?.toFixed(1)} / 10 <small>TMDB · {m.voteCount} votes</small></span>{/if}</div>
 {#if card.kind==='music'}<div class="artist-links">{#if people.length}{#each people as p}<button onclick={()=>person(m?.provider||'musicbrainz',p)}>{p.name}</button>{/each}{:else}{#each [...new Set(local.map(e=>trackMode?(e.id===card.entry?.id?e.metadata?.artist:undefined):(e.metadata?.albumArtist||e.metadata?.artist)).filter(Boolean))] as name}<button onclick={()=>artist(name!)}>{name}</button>{/each}{/if}</div>{/if}
 {#if m?.tagline}<p class="tagline">{m.tagline}</p>{/if}
 <div class="content-actions">{#if first}<button class="primary" onclick={()=>play(trackMode?card.entry!:first)}><Icon name="play" size={17}/>{first.position&&!first.completed?'Reprendre':'Lire'}{card.kind==='music'&&!trackMode?' l’album':''}</button>{/if}
 {#if work}<button class="secondary" disabled={busy} aria-pressed={work.watchlist} onclick={()=>toggle('watchlist')}>{work.watchlist?'✓ Dans ma liste':card.kind==='music'?'+ À écouter':'+ À voir'}</button><button class="secondary" disabled={busy} aria-pressed={work.favorite} onclick={()=>toggle('favorite')}>{work.favorite?'♥ Favori':'♡ Favori'}</button>{/if}
 {#if card.kind==='music'&&local.length}<button class="secondary" onclick={()=>enqueue(trackMode?[card.entry!]:sorted)}>À la file</button><button class="secondary" onclick={()=>playlist(trackMode?[card.entry!]:sorted)}>Ajouter à une playlist</button>{/if}
 {#if work&&card.kind!=='music'&&(!local.length||card.kind==='series')}<button class="secondary" disabled={!canRequest(card.kind)} onclick={()=>downloadSeason=-1}>{card.kind==='series'?'Demander la série':'Demander le téléchargement'}</button>{:else if !local.length&&card.kind==='music'}<button class="secondary" onclick={()=>requestLater(title)}>Demander le téléchargement <small>· bientôt</small></button>{/if}</div>
 {#if card.kind==='music'&&m?.edition}<p class="folder-help">Édition : {m.edition}</p>{/if}
 {#if card.kind!=='music'&&(permitted(local[0],'edit')||(!local.length&&currentAccount?.admin&&work))}<button class="text-action" onclick={()=>editingPoster=true}>Changer l’affiche</button>{/if}
 {#if card.kind!=='music'&&local[0]?.libraryId&&permitted(local[0],'edit')}<button class="text-action" onclick={()=>inspect(local[0])}>Corriger l’association</button>{/if}
 </div></section>
 {#if busy}<p class="folder-help" role="status">La fiche se complète…</p>{/if}{#if warning}<p class="notice" role="status">{warning}</p>{/if}{#if requested}<p class="notice" role="status">{requested}</p>{/if}
 {#if card.kind!=='music'}<div class="content-description"><section><h2>L’histoire</h2><p>{m?.overview||'Le résumé n’est pas encore disponible. Vous pouvez identifier cette œuvre depuis les informations du fichier.'}</p>{#if m?.trailers?.length}<div class="trailer-links">{#each m.trailers as trailer}<a class="trailer-card" href={trailer.url} target="_blank" rel="noreferrer"><span class="trailer-thumbnail">{#if trailer.thumbnail&&!failedTrailers[trailer.url]}<img src={trailer.thumbnail} alt="" loading="lazy" onerror={()=>failedTrailers={...failedTrailers,[trailer.url]:true}}/>{/if}<span class="trailer-play">▶</span></span><strong>{trailer.name} ↗</strong><small>{trailer.language==='fr'?'Français':trailer.language?trailer.language.toUpperCase():'Langue non précisée'}</small></a>{/each}<small>Bandes-annonces sur YouTube, dans un nouvel onglet.</small></div>{/if}</section><aside><h3>En quelques mots</h3><dl>{#if m?.releaseDate}<dt>Première sortie</dt><dd>{m.releaseDate}</dd>{/if}{#if m?.status}<dt>Statut</dt><dd>{m.status}</dd>{/if}{#if m?.countries?.length}<dt>Production</dt><dd>{m.countries.join(', ')}</dd>{/if}{#if m?.languages?.length}<dt>Langues d’origine</dt><dd>{m.languages.join(', ')}</dd>{/if}<dt>Dans Mosaune</dt><dd>{local.length?`${local.length} fichier(s) disponible(s)`:'Absent du serveur'}</dd></dl></aside></div>
 {#if m?.contributors?.length}<section class="cast-section"><h2>Les visages de l’histoire</h2><div class="cast-rail">{#each m.contributors as p}<button onclick={()=>person(m?.provider||'tmdb',p)}><Portrait name={p.name} image={p.image}/><strong>{p.name}</strong><small>{p.role}</small></button>{/each}</div></section>{:else if m?.cast?.length}<h2>Distribution</h2><p>{m.cast.join(' · ')}</p>{/if}
 {/if}
 {#if card.kind==='music'&&!trackMode}
 <section class="track-section"><div class="shelf-heading"><div><h2>Les morceaux</h2><p>{work?.metadata.tracks?.length?'Liste de l’édition MusicBrainz choisie. Les pistes absentes sont grisées.':'Fichiers présents sur votre serveur. Associez une édition pour connaître les pistes manquantes.'}</p></div>{#if local[0]?.metadata?.album}<button class="secondary" disabled={busy||!permitted(local[0],'edit')} onclick={()=>matching=true}>Corriger l’association</button>{/if}</div>

 {#if work?.metadata.tracks?.length}<ol class="album-tracks">{#each work.metadata.tracks as track,index}{@const entry=trackEntry(track,sorted)}<li class:missing-track={!entry}><span class="track-number">{track.disc>1?`${track.disc}.`:''}{track.number||index+1}</span><button class="track-title" onclick={()=>entry?openTrack(entry):requestLater(track.title)}><strong>{track.title}</strong><small>{track.artists?.map(a=>a.name).join(' · ')}</small></button><span class="track-duration">{track.duration?timeLabel(track.duration):'—'}</span>{#if entry}<button class="icon-button" aria-label={`Lire ${track.title}`} onclick={()=>play(entry)}><Icon name="play" size={17}/></button>{:else}<button class="text-action" onclick={()=>requestLater(track.title)}>Demander</button>{/if}</li>{/each}</ol>{/if}
 {#if !work?.metadata.tracks?.length||unmatched.length}{#if unmatched.length}<h3>Autres fichiers de cet album</h3><p class="folder-help">Ces fichiers ne sont pas rapprochés avec certitude des pistes de l’édition.</p>{/if}<ol class="album-tracks">{#each work?.metadata.tracks?.length?unmatched:sorted as entry,index}<li><span class="track-number">{entry.metadata?.track||index+1}</span><button class="track-title" onclick={()=>openTrack(entry)}><strong>{entry.metadata?.title||entry.name}</strong><small>{entry.metadata?.artist} · {entry.filename.split('.').pop()?.toUpperCase()}</small></button><button class="text-action" onclick={()=>playlist([entry])}>+ Playlist</button><button class="icon-button" aria-label={`Lire ${entry.name}`} onclick={()=>play(entry)}><Icon name="play" size={17}/></button></li>{/each}</ol>{/if}</section>
 {:else if card.kind!=='music'&&(local.length||seasonCards.length)}<section class="episode-section">{#if card.kind==='series'&&seasonCards.length}<div class="shelf-heading"><h2>Les saisons</h2><button class="text-action" onclick={()=>selectedSeason=null}>Tous mes épisodes</button></div><div class="season-rail">{#each seasonCards as season}{@const count=sorted.filter(e=>(e.metadata?.season??0)===season.number).length}<button class="season-card" class:selected={selectedSeason===season.number} aria-pressed={selectedSeason===season.number} onclick={()=>selectedSeason=season.number}><span class="season-cover">{#if season.image&&!failedSeasons[season.number]}<img src={season.image} alt="" loading="lazy" onerror={()=>failedSeasons={...failedSeasons,[season.number]:true}}/>{:else}<Icon name="series" size={32}/>{/if}<span>{count?'Chez vous':'À découvrir'}</span></span><strong>{season.name}</strong><small>{count} disponible(s){season.episodes?` / ${season.episodes} épisodes`:''}</small></button>{/each}</div>{/if}<h2>{card.kind==='series'?'Vos épisodes':'Vos fichiers'}</h2>{#if card.kind==='series'}<p class="folder-help">Seuls vos fichiers disponibles sont listés ; la série n’est pas nécessairement complète.</p>{/if}{#if selectedSeason!==null&&!seasonEntries.length}<p class="folder-help">Aucun épisode de cette saison sur votre serveur.</p>{/if}{#if selectedSeason!==null&&work}<button class="secondary" disabled={!canRequest(card.kind)} onclick={()=>downloadSeason=selectedSeason}>Demander cette saison</button>{/if}{#each seasonEntries as entry,index}{#if entry.kind==='series'&&(index===0||entry.metadata?.season!==seasonEntries[index-1].metadata?.season)}<h3>Saison {entry.metadata?.season??0}</h3>{/if}<div class="episode-item"><button class="episode-title" onclick={()=>play(entry)}><span>{entry.kind==='series'?String(entry.metadata?.episode??0).padStart(2,'0'):'▶'}</span><div><strong>{entry.metadata?.title||entry.name}</strong><small>{entry.completed?'Vu':entry.position?`Reprendre à ${timeLabel(entry.position)}`:'Prêt à regarder'}</small></div></button><div class="episode-actions"><button class="text-action" onclick={()=>mark(entry,!entry.completed)}>{entry.completed?'Marquer non vu':'Marquer vu'}</button><button class="text-action" onclick={()=>inspect(entry)}>Infos fichier</button></div></div>{/each}</section>
 {:else if trackMode&&card.entry}<section class="track-section"><h2>Dans votre collection</h2><p>{card.entry.filename}</p><div class="content-actions"><button class="secondary" onclick={()=>mark(card.entry!,!card.entry?.completed)}>{card.entry.completed?'Marquer non écouté':'Marquer écouté'}</button><button class="secondary" onclick={()=>inspect(card.entry!)}>Informations du fichier</button></div>{#if album}<button class="album-return" onclick={()=>open(groupCard(album))}>Retrouver l’album « {album.title} » →</button>{/if}</section>{/if}
 {#if related.length}<MediaShelf title={card.kind==='music'?'Du même artiste, à explorer':'Si cette histoire vous plaît'} subtitle={card.kind==='music'?'Autres éditions et projets référencés par MusicBrainz.':'Suggestions TMDB à partir de cette œuvre.'} cards={related.map(workCard)} {open}/>{/if}
 <p class="content-source">{work?`Informations : ${providers.find(p=>p.id===work?.metadata.provider)?.name||work.metadata.provider}`:'Informations issues de vos fichiers'} · Votre collection reste chez vous.</p>
</article>

{#if matching&&local[0]}<AlbumMatch entry={local[0]} {token} {matched} close={()=>matching=false}/>{/if}

{#if downloadSeason!==null&&work}<RequestDownload {work} season={downloadSeason} {token} close={()=>downloadSeason=null}/>{/if}
